-- W8 상점 기본 목록(S15P31A207-299, contract-W8.md 3절, 사용자 결정 A1: 4부위 유지 + 잠긴 아이템).
-- 운영 기준값 SHOP_ITEMS 행이 없거나 목록이 비었을 때만 넣는다(기본값 {"items":[]}). 아이템이 하나라도 있는 운영자 목록은 건드리지 않는다
-- (D-44: 아이템 ID 삭제·부위 변경 금지. 목록이 비었으면 보유·착용 중인 아이템 ID도 없다).
-- 아이템마다 앱 그림 키(assetKey)를 두고, 잠긴 아이템은 해금 조건(unlock: kind, threshold, text)을 둔다. local 프로필은 import-local.sql에 같은 값이 있다.
UPDATE operation_setting
SET setting_value = '{"items":[{"id":1,"name":"라임 싱글렛","slot":"TOP","price":300,"onSale":true,"assetKey":"top_lime_singlet"},{"id":2,"name":"새벽 바람막이","slot":"TOP","price":500,"onSale":true,"assetKey":"top_dawn_windbreaker"},{"id":3,"name":"크루 티셔츠","slot":"TOP","price":300,"onSale":true,"assetKey":"top_crew_tee"},{"id":4,"name":"겨울 후디","slot":"TOP","price":700,"onSale":true,"assetKey":"top_winter_hoodie"},{"id":5,"name":"체리 조끼","slot":"TOP","price":400,"onSale":true,"assetKey":"top_cherry_vest"},{"id":6,"name":"완주 기념 티","slot":"TOP","price":300,"onSale":true,"assetKey":"top_finisher_tee","unlock":{"kind":"LONGEST_RUN","threshold":21097,"text":"하프 완주하면 열려요"}},{"id":11,"name":"러닝 반바지","slot":"BOTTOM","price":300,"onSale":true,"assetKey":"bottom_running_shorts"},{"id":12,"name":"조거 팬츠","slot":"BOTTOM","price":500,"onSale":true,"assetKey":"bottom_jogger_pants"},{"id":13,"name":"러닝 레깅스","slot":"BOTTOM","price":400,"onSale":true,"assetKey":"bottom_leggings"},{"id":21,"name":"기본 러닝화","slot":"SHOES","price":400,"onSale":true,"assetKey":"shoes_basic_runner"},{"id":22,"name":"라임 러닝화","slot":"SHOES","price":600,"onSale":true,"assetKey":"shoes_lime_runner"},{"id":23,"name":"카본 레이싱화","slot":"SHOES","price":900,"onSale":true,"assetKey":"shoes_carbon_racer","unlock":{"kind":"TOTAL_DISTANCE","threshold":100000,"text":"누적 100km 달리면 열려요"}},{"id":31,"name":"러닝 캡","slot":"HAT","price":200,"onSale":true,"assetKey":"hat_running_cap"},{"id":32,"name":"헤어밴드","slot":"HAT","price":200,"onSale":true,"assetKey":"hat_headband"},{"id":33,"name":"비니","slot":"HAT","price":300,"onSale":true,"assetKey":"hat_beanie"},{"id":34,"name":"열 번 기념 캡","slot":"HAT","price":300,"onSale":true,"assetKey":"hat_ten_runs_cap","unlock":{"kind":"RUN_COUNT","threshold":10,"text":"10번 달리면 열려요"}}]}',
    version       = version + 1,
    updated_at    = CAST(now() AT TIME ZONE 'Asia/Seoul' AS TIMESTAMP(6))
WHERE setting_key = 'SHOP_ITEMS'
  AND CASE
          WHEN setting_value IS NOT JSON OBJECT THEN FALSE
          WHEN jsonb_typeof(setting_value::jsonb -> 'items') IS DISTINCT FROM 'array' THEN FALSE
          ELSE jsonb_array_length(setting_value::jsonb -> 'items') = 0
      END;

INSERT INTO operation_setting (setting_key, setting_value, version, updated_at)
SELECT 'SHOP_ITEMS',
       '{"items":[{"id":1,"name":"라임 싱글렛","slot":"TOP","price":300,"onSale":true,"assetKey":"top_lime_singlet"},{"id":2,"name":"새벽 바람막이","slot":"TOP","price":500,"onSale":true,"assetKey":"top_dawn_windbreaker"},{"id":3,"name":"크루 티셔츠","slot":"TOP","price":300,"onSale":true,"assetKey":"top_crew_tee"},{"id":4,"name":"겨울 후디","slot":"TOP","price":700,"onSale":true,"assetKey":"top_winter_hoodie"},{"id":5,"name":"체리 조끼","slot":"TOP","price":400,"onSale":true,"assetKey":"top_cherry_vest"},{"id":6,"name":"완주 기념 티","slot":"TOP","price":300,"onSale":true,"assetKey":"top_finisher_tee","unlock":{"kind":"LONGEST_RUN","threshold":21097,"text":"하프 완주하면 열려요"}},{"id":11,"name":"러닝 반바지","slot":"BOTTOM","price":300,"onSale":true,"assetKey":"bottom_running_shorts"},{"id":12,"name":"조거 팬츠","slot":"BOTTOM","price":500,"onSale":true,"assetKey":"bottom_jogger_pants"},{"id":13,"name":"러닝 레깅스","slot":"BOTTOM","price":400,"onSale":true,"assetKey":"bottom_leggings"},{"id":21,"name":"기본 러닝화","slot":"SHOES","price":400,"onSale":true,"assetKey":"shoes_basic_runner"},{"id":22,"name":"라임 러닝화","slot":"SHOES","price":600,"onSale":true,"assetKey":"shoes_lime_runner"},{"id":23,"name":"카본 레이싱화","slot":"SHOES","price":900,"onSale":true,"assetKey":"shoes_carbon_racer","unlock":{"kind":"TOTAL_DISTANCE","threshold":100000,"text":"누적 100km 달리면 열려요"}},{"id":31,"name":"러닝 캡","slot":"HAT","price":200,"onSale":true,"assetKey":"hat_running_cap"},{"id":32,"name":"헤어밴드","slot":"HAT","price":200,"onSale":true,"assetKey":"hat_headband"},{"id":33,"name":"비니","slot":"HAT","price":300,"onSale":true,"assetKey":"hat_beanie"},{"id":34,"name":"열 번 기념 캡","slot":"HAT","price":300,"onSale":true,"assetKey":"hat_ten_runs_cap","unlock":{"kind":"RUN_COUNT","threshold":10,"text":"10번 달리면 열려요"}}]}',
       0,
       CAST(now() AT TIME ZONE 'Asia/Seoul' AS TIMESTAMP(6))
WHERE NOT EXISTS (SELECT 1 FROM operation_setting WHERE setting_key = 'SHOP_ITEMS');
